 void quality(){heading("Calidad a tu medida","Equilibra nitidez, fluidez y espacio.");LinearLayout c=card(root);section(c,"Vídeo",null,"screen");select(c,"Resolución","quality",new String[]{"480p · Ahorro","720p · Equilibrada","1080p · Alta calidad"},1,"screen");select(c,"Fotogramas por segundo","fps",new String[]{"24 FPS","30 FPS","60 FPS"},1,"speed");select(c,"Tasa de vídeo","bitrate",new String[]{"2 Mbps","4 Mbps","8 Mbps","12 Mbps"},1,"sliders");LinearLayout a=card(root);section(a,"Audio","Añade tu voz a la grabación.","mic");Switch mic=new Switch(this);mic.setText("Grabar micrófono");mic.setTextColor(WHITE);mic.setTextSize(14);mic.setMinimumHeight(dp(48));mic.setThumbTintList(ColorStateList.valueOf(RED));mic.setChecked(prefs.getBoolean("mic",false));a.addView(mic);mic.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean("mic",on).apply());gap(a,12);a.addView(small("El permiso se solicita al grabar. Audio interno no incluido."));root.addView(small("La disponibilidad de 1080p y 60 FPS depende del dispositivo. Los cambios se aplican en la próxima sesión."));}
 void floating(){heading("Un botón muy tuyo","Personaliza el control que te acompaña.");LinearLayout preview=card(root);section(preview,"Tu control flotante","Imagen, tamaño y transparencia de tu control.","float");FrameLayout stage=new FrameLayout(this);stage.setBackground(bg(0xffededed,20));preview.addView(stage,new LinearLayout.LayoutParams(-1,dp(164)));ImageView image=new ImageView(this);File f=new File(getFilesDir(),"bubble.png");if(f.exists())image.setImageBitmap(BitmapFactory.decodeFile(f.toString()));else image.setImageResource(R.drawable.ic_ghost);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(bg(Color.BLACK,64));image.setClipToOutline(true);int sz=dp(new int[]{40,52,64}[prefs.getInt("size",1)]);image.setAlpha(new float[]{.5f,.75f,1f}[prefs.getInt("alpha",2)]);stage.addView(image,new FrameLayout.LayoutParams(sz,sz,Gravity.CENTER));action(preview,"Elegir mi imagen","image",true,()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);});action(preview,"Restaurar icono Xato","reset",false,()->{new File(getFilesDir(),"bubble.png").delete();render();});LinearLayout c=card(root);select(c,"Tamaño","size",new String[]{"40 dp · Compacto","52 dp · Equilibrado","64 dp · Grande"},1,"float");select(c,"Opacidad","alpha",new String[]{"50 % · Discreto","75 % · Suave","100 % · Sólido"},2,"sun");LinearLayout visibility=card(root);Switch floatingSwitch=new Switch(this);floatingSwitch.setText("Mostrar al grabar");floatingSwitch.setTextColor(WHITE);floatingSwitch.setTextSize(14);floatingSwitch.setMinimumHeight(dp(48));floatingSwitch.setChecked(prefs.getBoolean("floating",true));visibility.addView(floatingSwitch);floatingSwitch.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean("floating",on).apply());gap(visibility,8);visibility.addView(small("Tu fantasma será el icono predeterminado. Puedes cambiarlo por otra imagen."));LinearLayout access=card(root);boolean allowed=Settings.canDrawOverlays(this);section(access,"Mostrar sobre otras apps",allowed?"Permiso activado":"Necesita permiso de superposición.","shield");action(access,"Abrir permiso del flotante","chevron",false,()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));root.addView(small("Arrastra para mover y toca para ver los controles. El botón puede aparecer en el vídeo. Los cambios se aplican al iniciar otra grabación."));}
 void library(){heading("Tus grabaciones","Tus momentos, guardados en tu dispositivo.");LinearLayout c=card(root);FrameLayout art=new FrameLayout(this);art.setBackground(bg(0xffeeeeee,24));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(88),dp(88));ap.gravity=Gravity.CENTER_HORIZONTAL;c.addView(art,ap);art.addView(new Glyph("folder",RED),new FrameLayout.LayoutParams(dp(40),dp(40),Gravity.CENTER));gap(c,24);TextView title=text("Tu próxima gran captura",20,WHITE,true);title.setGravity(Gravity.CENTER);c.addView(title);gap(c,10);TextView desc=small("Encuentra tus vídeos en la galería de Android, dentro de Movies/XatoRecord.");desc.setGravity(Gravity.CENTER);c.addView(desc);gap(c,12);action(c,"Abrir galería de vídeos","folder",true,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI));}catch(Exception e){Toast.makeText(this,"Abre Galería → Movies/XatoRecord",1).show();}});LinearLayout info=card(root);section(info,"Hecho para ser ligero","MP4 estándar, guardado local y sin conexión a Internet.","shield");info.addView(small("No incluye editor ni audio interno. Algunas aplicaciones impiden capturar su contenido."));}
 void openDrawer(){if(drawer!=null)return;FrameLayout overlay=new FrameLayout(this);overlay.setBackgroundColor(0xaa000000);shell.addView(overlay,new FrameLayout.LayoutParams(-1,-1));drawer=overlay;overlay.setOnClickListener(v->closeDrawer());LinearLayout panel=col();panel.setPadding(dp(24),dp(56),dp(24),dp(24));panel.setBackground(bg(Color.WHITE,24));int width=Math.min(dp(300),getResources().getDisplayMetrics().widthPixels-dp(48));overlay.addView(panel,new FrameLayout.LayoutParams(width,-1,Gravity.LEFT));panel.setOnClickListener(v->{});ImageView mark=new ImageView(this);mark.setImageResource(R.drawable.ic_ghost);mark.setBackground(bg(Color.BLACK,16));mark.setClipToOutline(true);panel.addView(mark,new LinearLayout.LayoutParams(dp(56),dp(56)));gap(panel,20);panel.addView(text("XatoRecord",26,WHITE,true));gap(panel,6);panel.addView(small("Haz que cada captura cuente."));gap(panel,32);String[] names={"Grabar pantalla","Calidad y audio","Botón flotante","Mis vídeos"},icons={"record","sliders","float","folder"};for(int i=0;i<4;i++){final int n=i;action(panel,names[i],icons[i],page==i,()->{closeDrawer();page=n;render();});}Space space=new Space(this);panel.addView(space,new LinearLayout.LayoutParams(1,0,1));panel.addView(small("DISEÑADO POR XATO D3V"));gap(panel,8);panel.addView(text("Pantalla · Versión 0.3",12,MUTED,false));panel.setTranslationX(-width);panel.animate().translationX(0).setDuration(220).start();}
