 class Glyph extends View {String name;Paint p=new Paint(3);int color;Glyph(String n,int c){super(MainActivity.this);name=n;color=c;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}void line(Canvas c,float a,float b,float x,float y){c.drawLine(a,b,x,y,p);}protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.scale(getWidth()/24f,getHeight()/24f);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.7f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);Canvas c=canvas;
 switch(name){case "menu":line(c,4,6,20,6);line(c,4,12,16,12);line(c,4,18,20,18);break;case "record":c.drawCircle(12,12,9,p);p.setStyle(Paint.Style.FILL);c.drawCircle(12,12,4,p);break;case "stop":c.drawRoundRect(5,5,19,19,3,3,p);break;case "pause":line(c,8,5,8,19);line(c,16,5,16,19);break;case "chevron":line(c,9,6,15,12);line(c,15,12,9,18);break;case "screen":c.drawRoundRect(3,4,21,17,3,3,p);line(c,9,21,15,21);line(c,12,17,12,21);break;case "folder":{Path f=new Path();f.moveTo(3,7);f.lineTo(3,19);f.quadTo(3,21,5,21);f.lineTo(19,21);f.quadTo(21,21,21,19);f.lineTo(21,8);f.lineTo(12,8);f.lineTo(10,5);f.lineTo(5,5);f.quadTo(3,5,3,7);c.drawPath(f,p);break;}case "mic":c.drawRoundRect(9,3,15,14,3,3,p);c.drawArc(6,6,18,18,0,180,false,p);line(c,12,18,12,21);line(c,9,21,15,21);break;case "float":c.drawRoundRect(3,3,21,21,5,5,p);c.drawCircle(15,15,3,p);break;case "sliders":line(c,3,7,21,7);line(c,3,17,21,17);p.setStyle(Paint.Style.FILL);c.drawCircle(8,7,3,p);c.drawCircle(16,17,3,p);break;case "speed":c.drawArc(3,3,21,21,150,240,false,p);line(c,12,12,17,7);c.drawCircle(12,12,1,p);break;case "image":c.drawRoundRect(3,3,21,21,3,3,p);c.drawCircle(8,8,1.5f,p);line(c,4,18,10,12);line(c,10,12,14,16);line(c,14,16,18,11);line(c,18,11,21,15);break;case "reset":c.drawArc(5,5,20,20,-100,290,false,p);line(c,5,5,5,11);line(c,5,11,11,11);break;case "sun":c.drawCircle(12,12,4,p);for(int i=0;i<8;i++){double a=i*Math.PI/4;line(c,12+(float)Math.cos(a)*7,12+(float)Math.sin(a)*7,12+(float)Math.cos(a)*9,12+(float)Math.sin(a)*9);}break;case "shield":Path sh=new Path();sh.moveTo(12,3);sh.lineTo(20,6);sh.lineTo(19,14);sh.quadTo(18,19,12,22);sh.quadTo(6,19,5,14);sh.lineTo(4,6);sh.close();c.drawPath(sh,p);line(c,8,12,11,15);line(c,11,15,16,10);break;default:c.drawCircle(12,12,8,p);}
 canvas.restore();}}
 void command(String a){if(!RecordService.running){Toast.makeText(this,"No hay grabación activa",0).show();return;}startService(new Intent(this,RecordService.class).setAction(a));}
 void begin(){if(RecordService.running){Toast.makeText(this,"Ya hay una grabación activa",0).show();return;}requestedMic=prefs.getBoolean("mic",false);if(requestedMic&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},30);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},31);return;}capture();}
 void capture(){startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(),10);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==30){if(g.length>0&&g[0]==0)begin();else Toast.makeText(this,"Desactiva micrófono o concede el permiso",1).show();}if(r==31)capture();}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==10&&result==RESULT_OK&&data!=null){startForegroundService(new Intent(this,RecordService.class).setAction("START").putExtra("data",data).putExtra("mic",requestedMic));}if(req==20&&result==RESULT_OK&&data!=null){try{android.graphics.ImageDecoder.Source src=android.graphics.ImageDecoder.createSource(getContentResolver(),data.getData());android.graphics.Bitmap b=android.graphics.ImageDecoder.decodeBitmap(src,(decoder,info,source)->decoder.setTargetSize(Math.max(1,(int)(info.getSize().getWidth()*Math.min(192.0/info.getSize().getWidth(),192.0/info.getSize().getHeight()))),Math.max(1,(int)(info.getSize().getHeight()*Math.min(192.0/info.getSize().getWidth(),192.0/info.getSize().getHeight())))));try(FileOutputStream out=new FileOutputStream(new File(getFilesDir(),"bubble.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();render();Toast.makeText(this,"Imagen lista para la próxima grabación",0).show();}catch(Exception e){Toast.makeText(this,"No se pudo leer la imagen",1).show();}}}
